const n=async()=>{try{const t=await fetch("http://localhost:5001/port");if(!t.ok)throw new Error("Port endpoint not reachable");const o=await t.json();if(!o||!o.port)throw new Error("Invalid port response");return`http://localhost:${o.port}`}catch{for(let t=5001;t<=5100;t++)try{const o=new AbortController,r=setTimeout(()=>o.abort(),500),e=await fetch(`http://localhost:${t}/health`,{signal:o.signal});if(clearTimeout(r),e.ok)return`http://localhost:${t}`}catch{}return null}};export{n as getBackendUrl};
